sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_aSpeed;
uniform float amzp_progress;
uniform float amzp_mode;
uniform float amzp_cols;
uniform float amzp_rows;
uniform float amzp_scrAmt;
uniform float amzp_changes;
uniform float amzp_range;
uniform float amzp_gap;
uniform float amzp_gapMode;
layout(color) uniform half4 amzp_gapCol;
uniform float amzp_flipChance;
uniform float amzp_rotChance;
uniform float amzp_colorShift;
uniform float amzp_brightRand;
uniform float amzp_edgeMode;
uniform float amzp_seed;
uniform float amzp_mixAmt;
uniform float amzp_overdrawOn;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float4 layerClamp(float2 uv) { return amzTexture(0, l2s(clamp(uv, 0.0, 1.0))); }
    float TT() { return (amzp_autop>0.5) ? amzp_progress + time * amzp_aSpeed : amzp_progress; }
    float hs(float3 p) {
        p = fract(p * float3(0.1031, 0.1030, 0.0973) + amzp_seed * 0.0137);
        p += dot(p, p.yzx + 33.33);
        return fract((p.x + p.y) * p.z);
    }
    float2 edgeUV(float2 uv) {
        if (int(amzp_edgeMode) == 0) return 1.0 - abs(1.0 - mod(uv, 2.0));
        if (int(amzp_edgeMode) == 1) return fract(uv);
        return uv;
    }
    float edgeIdx(float i, float n) {
        if (int(amzp_edgeMode) == 0) { float m = mod(i, 2.0 * n); return m < n ? m : 2.0 * n - 1.0 - m; }
        if (int(amzp_edgeMode) == 1) return mod(i, n);
        return i;
    }
    float3 hueRot(float3 c, float a) {
        const float3 k = float3(0.57735);
        float ca = cos(a);
        return c * ca + cross(k, c) * sin(a) + k * dot(k, c) * (1.0 - ca);
    }
    void amzRender() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float4 orig = layerAt(uv);
        float2 G = float2(max(floor(amzp_cols + 0.5), 1.0), max(floor(amzp_rows + 0.5), 1.0));
        float t = TT();
        float stp = amzp_changes > 0.0 ? floor(t * amzp_changes) : 0.0;
        float2 cell = floor(uv * G);
        float2 f = fract(uv * G);
        float rng = max(amzp_range, 0.0);
        bool moved = hs(float3(cell, stp + 11.0)) < amzp_scrAmt;
        float2 suv = uv;
        float2 tid = cell;
        if (int(amzp_mode) == 0) {
            float2 sc = cell;
            if (moved) {
                float2 rv = float2(hs(float3(cell, stp + 1.7)), hs(float3(cell.yx, stp + 5.3))) - 0.5;
                sc = cell + floor(rv * 2.0 * rng * G + 0.5);
            }
            bool outC = sc.x < 0.0 || sc.y < 0.0 || sc.x >= G.x || sc.y >= G.y;
            sc = float2(edgeIdx(sc.x, G.x), edgeIdx(sc.y, G.y));
            float2 lf = f;
            if (moved && hs(float3(cell, stp + 23.0)) < amzp_flipChance) { if (hs(float3(cell, stp + 29.0)) < 0.5) lf.x = 1.0 - lf.x; else lf.y = 1.0 - lf.y; }
            if (moved && hs(float3(cell, stp + 31.0)) < amzp_rotChance) {
                float q = floor(hs(float3(cell, stp + 37.0)) * 3.0);
                if (q < 0.5) lf = float2(lf.y, 1.0 - lf.x); else if (q < 1.5) lf = 1.0 - lf; else lf = float2(1.0 - lf.y, lf.x);
            }
            suv = (sc + lf) / G;
            if (outC && int(amzp_edgeMode) == 2) suv = float2(-1.0);
            tid = cell;
        } else if (int(amzp_mode) == 1) {
            tid = float2(0.0, cell.y);
            if (hs(float3(tid, stp + 11.0)) < amzp_scrAmt) suv.x += (hs(float3(tid, stp + 3.1)) - 0.5) * 2.0 * rng;
            suv = edgeUV(suv);
        } else if (int(amzp_mode) == 2) {
            tid = float2(cell.x, 0.0);
            if (hs(float3(tid, stp + 11.0)) < amzp_scrAmt) suv.y += (hs(float3(tid, stp + 3.1)) - 0.5) * 2.0 * rng;
            suv = edgeUV(suv);
        } else {
            if (moved) suv += (float2(hs(float3(cell, stp + 1.7)), hs(float3(cell.yx, stp + 5.3))) - 0.5) * 2.0 * rng * 2.0 / G;
            suv = edgeUV(suv);
        }
        float4 R = layerAt(suv);
        bool tileMoved = int(amzp_mode) == 0 || int(amzp_mode) == 3 ? moved : hs(float3(tid, stp + 11.0)) < amzp_scrAmt;
        if (tileMoved && R.a > 0.0001 && (amzp_colorShift > 0.0 || amzp_brightRand > 0.0)) {
            float3 c = R.rgb / R.a;
            c = hueRot(c, (hs(float3(tid, stp + 41.0)) - 0.5) * 6.28318531 * amzp_colorShift);
            c *= 1.0 + (hs(float3(tid, stp + 43.0)) - 0.5) * 2.0 * amzp_brightRand;
            R.rgb = clamp(c, 0.0, 1.0) * R.a;
        }
        if (amzp_gap > 0.0) {
            float2 cp = W / G;
            float2 e = min(f, 1.0 - f) * cp;
            float hg = amzp_gap * pxs() * 0.5;
            float m = 1.0 - smoothstep(hg - 0.75, hg + 0.75, min(e.x, e.y));
            float4 gc = int(amzp_gapMode) == 1 ? float4(amzp_gapCol.rgb, 1.0) : float4(0.0);
            R = mix(R, gc, m);
        }
        R = mix(orig, R, clamp(amzp_mixAmt, 0.0, 1.0));
        amzOutput = R;
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
